mapper.select:
select pos_id as posId, pos_title as title, pos_department as dept, pos_work_city as city, pos_salary_min as salaryMin, pos_salary_max as salaryMax, pos_experience_required as experience, pos_education_required as education, pos_status as status, date_format(pos_created_at, '%m-%d') as date, pos_jd_json as jdJson, (select count(*) from t_process_instance pi where pi.pin_position_id = p.pos_id) as applicantCount from t_pos p where p.pos_company_id = #{companyId}
and (p.pos_title like concat('%', #{keyword}, '%') or p.pos_department like concat('%', #{keyword}, '%'))
and p.pos_department = #{dept}
and p.pos_status = #{status}
order by p.pos_created_at desc, p.pos_id desc

mapper.update:
update t_process_template
set ptl_version = concat('v', cast(cast(substring(ptl_version, 2) as decimal(6,1)) + 0.1 as char))
where ptl_id = #{templateId}
